package shop.ultimatesmp.crates;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;
class CrateDeliveryTest {
 static final NamespacedKey KEY=new NamespacedKey("ultimatecrates","key");
 static ItemStack key(int count){ItemStack key=CratesTest.item(Material.TRIPWIRE_HOOK,count,"common-key");ItemMeta meta=mock(ItemMeta.class);PersistentDataContainer tags=mock(PersistentDataContainer.class);when(key.hasItemMeta()).thenReturn(true);when(key.getItemMeta()).thenReturn(meta);when(meta.getPersistentDataContainer()).thenReturn(tags);when(tags.get(KEY,PersistentDataType.STRING)).thenReturn("common");when(key.clone()).thenAnswer(c->key(key.getAmount()));return key;}
 static void field(Object instance,String name,Object value)throws Exception{Field f=UltimateCrates.class.getDeclaredField(name);f.setAccessible(true);f.set(instance,value);}
 static boolean deliver(UltimateCrates plugin,Player p,Crate crate,ItemStack reward)throws Exception{Method m=UltimateCrates.class.getDeclaredMethod("deliverReward",Player.class,Crate.class,ItemStack.class);m.setAccessible(true);return (Boolean)m.invoke(plugin,p,crate,reward);}
 static class Fixture {
  final UltimateCrates plugin=mock(UltimateCrates.class,CALLS_REAL_METHODS);final Player player=mock(Player.class);final PlayerInventory inv=mock(PlayerInventory.class);final AtomicReference<ItemStack[]> storage=new AtomicReference<>();final AtomicReference<ItemStack> offhand=new AtomicReference<>(CratesTest.item(Material.AIR,0,"air"));final ItemStack prize=CratesTest.item(Material.DIAMOND,1,"reward");final Crate crate=new Crate("common","Common",1,List.of(new Crate.Reward(prize,1)));
  Fixture(ItemStack... initial)throws Exception{field(plugin,"loaded",true);field(plugin,"keyId",KEY);when(player.isOnline()).thenReturn(true);when(player.getInventory()).thenReturn(inv);storage.set(initial);when(inv.getStorageContents()).thenAnswer(c->storage.get());doAnswer(c->{storage.set(c.getArgument(0));return null;}).when(inv).setStorageContents(any(ItemStack[].class));when(inv.getItemInOffHand()).thenAnswer(c->offhand.get());doAnswer(c->{offhand.set(c.getArgument(0));return null;}).when(inv).setItemInOffHand(any());}
  boolean deliver()throws Exception{return CrateDeliveryTest.deliver(plugin,player,crate,prize);}
 }
 @Test void completionConsumesOneKeyAndUsesCurrentInventoryInsteadOfTheOldPlan()throws Exception{var f=new Fixture(key(1),null,null);ItemStack newlyReceived=CratesTest.item(Material.EMERALD,3,"other");f.storage.set(new ItemStack[]{newlyReceived,key(1),null});assertTrue(f.deliver());assertEquals(Material.EMERALD,f.storage.get()[0].getType());assertEquals(3,f.storage.get()[0].getAmount());assertEquals(Material.DIAMOND,f.storage.get()[1].getType());assertNull(f.storage.get()[2]);verify(f.inv,times(1)).setStorageContents(any());}
 @Test void missingKeyCancelsAndDoesNotMutateInventory()throws Exception{var f=new Fixture(CratesTest.item(Material.EMERALD,3,"other"),null);assertFalse(f.deliver());verify(f.inv,never()).setStorageContents(any());verify(f.inv,never()).setItemInOffHand(any());}
 @Test void spaceLostDuringSpinCancelsAndKeepsTheKey()throws Exception{var f=new Fixture(key(2),CratesTest.item(Material.STONE,64,"full"));assertFalse(f.deliver());assertEquals(2,f.storage.get()[0].getAmount());verify(f.inv,never()).setStorageContents(any());}
 @Test void offhandKeyIsOnlyConsumedWhenTheCompletedRewardFits()throws Exception{var f=new Fixture((ItemStack)null);f.offhand.set(key(2));assertTrue(f.deliver());assertEquals(1,f.offhand.get().getAmount());assertEquals(Material.DIAMOND,f.storage.get()[0].getType());}
 @Test void networkFenceAndOfflinePlayerCannotCommit()throws Exception{var f=new Fixture(key(1),null);field(f.plugin,"loaded",false);assertFalse(f.deliver());field(f.plugin,"loaded",true);when(f.player.isDead()).thenReturn(true);assertFalse(f.deliver());when(f.player.isDead()).thenReturn(false);when(f.player.isOnline()).thenReturn(false);assertFalse(f.deliver());verify(f.inv,never()).setStorageContents(any());}
}
